import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`outdoor-tour-audit`,heroTitle:`Audit your outdoor tours in minutes`,heroSubtitle:`Perplexity Computer reviews your tour pages, booking flow, and local trust signals, then turns the gaps into a clearer plan to win more bookings.`,inputUrlCta:`Audit my tours`,inputUrlPlaceholder:`yourtourcompany.com`,inputUrlPrefill:`Go to {url} and run a full growth audit for this outdoor tour business. (1) Review the site for tour clarity, itinerary detail, pricing presentation, booking friction, mobile usability, and trust signals. (2) Analyze reviews, local search visibility, and social proof for the main tours this business sells. (3) Benchmark nearby competitors on positioning, tour packaging, photography, seasonal messaging, and booking flow. (4) Identify the biggest issues hurting conversion and repeat bookings. (5) Deliver a prioritized plan with page rewrites, offer ideas, trust improvements, and seasonal marketing recommendations.`,heroOverlaySteps:[`Reviewing tour pages, booking flow, pricing, and trust signals`,`Benchmarking local competitors on positioning, reviews, and conversion cues`,`Finding the friction points that are costing bookings and repeat demand`,`Growth plan with rewrites, offer ideas, and seasonal actions ready to use`],generatingSteps:[`Visiting {url} to understand the tours, booking experience, and current positioning`,`Designing an agent to benchmark competitor offers, reviews, and seasonal messaging`,`Configuring recommendations for booking conversion, trust, and local discovery`,`Packaging the work into a prioritized outdoor-tour growth plan`],featureSectionTitle:`From booking friction to a clearer growth plan`,featureCardTitles:[`Connects to your local growth workflow`,`Outputs your team can use`],featureCardDescriptions:[`Computer splits the work into site review, competitor analysis, local presence checks, and offer planning so the audit stays grounded in how people book tours.`,`Docs, Sheets, booking notes, and planning tools can stay connected so rewrites, offer tests, and seasonal ideas stay organized.`,`Tour-page rewrites. Booking fixes. Offer ideas. Seasonal promotions. Computer gives your team the next moves most likely to improve bookings.`],capabilitySectionTitle:`Your tour growth analyst, on autopilot`,capabilitySectionSubtitle:`Paste your site, step away, and come back to a sharper plan to sell more tours.`,capabilityCards:[{title:`Booking Flow Audit`,description:`Computer can review itinerary pages, pricing presentation, checkout friction, and mobile usability to show where prospective guests drop off.`},{title:`Competitor Benchmarking`,description:`Computer can compare your tours against nearby operators on packaging, trust signals, photography, and offer framing.`},{title:`Trust & Review Analysis`,description:`Computer can assess reviews, proof elements, and guest reassurance signals to show what is helping or hurting conversions.`},{title:`Connect Your Tools`,description:`Computer can organize audit notes, rewrites, and campaign ideas across Docs, Sheets, and planning tools so the work is easier to execute.`},{title:`Seasonal Offer Ideas`,description:`Computer can suggest seasonal campaigns, upsells, and packaging changes that better match how demand shifts through the year.`},{title:`Repeat the Audit`,description:`Computer can revisit the market later and update the recommendations as competitors, reviews, and seasonal demand evolve.`}]});export{t as default};
